512	                    // 审核先拿锁：点列快照必须是版本 1 的旧点 y=10
513	                    ReviewResultDto dto = dataOf(mr);
514	                    assertEquals(1, dto.routeVersion());
515	                    assertEquals(10, dto.pointsSnapshot().get(0).y());
516	                } else {
