                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {"zoneId":"z2","requestId":"req-v6"}"""))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.code").value("ZONE_ALREADY_REVOKED"));
    }
