60	    private void runRounds(int iterations, boolean zoneFirst) throws Exception {
61	        int clearByOldSnapshot = 0;
62	        int conflictByCommittedZone = 0;
63	        ExecutorService pool = Executors.newFixedThreadPool(4);
64	        try {
65	            for (int i = 0; i < iterations; i++) {
66	                int iter = i;
67	                cleanup();
68	                String routeId = "pr" + iter;
69	                String zoneId = "pz" + iter;
70	                service.createRoute(new RouteCreateRequest(routeId,
71	                        List.of(new RoutePointDto(0, 10), new RoutePointDto(100, 10)),
72	                        "preq-route-" + iter));
73	
74	                Future<Object> zoneFuture;
75	                Future<Object> reviewFuture;
76	                if (zoneFirst) {
77	                    // 建区先完整提交，再立即用旧空域版本发起审核
78	                    Object zr = service.createZone(new ZoneCreateRequest(
79	                            zoneId, 40, 5, 60, 15, "preq-zone-" + iter));
