83	                        done.countDown();
84	                        try {
85	                            return service.review(
86	                                    new ReviewRequest(routeId, 1, 0L, "preq-rv-" + iter));
87	                        } catch (ApiException ex) {
88	                            return ex;
89	                        }
90	                    });
91	                    done.await(5, TimeUnit.SECONDS);
92	                    zoneFuture = java.util.concurrent.CompletableFuture.completedFuture(zr);
93	                } else {
94	                    CyclicBarrier barrier = new CyclicBarrier(2);
