107	                            return service.createZone(new ZoneCreateRequest(
108	                                    zoneId, 40, 5, 60, 15, "preq-zone-" + iter));
109	                        } catch (ApiException ex) {
110	                            return ex;
111	                        }
112	                    });
113	                }
114	
115	                Object reviewResult = reviewFuture.get(15, TimeUnit.SECONDS);
116	                Object zoneResult = zoneFuture.get(15, TimeUnit.SECONDS);
117	                assertTrue(zoneResult instanceof MutationResponse, "建区必须成功一次");
118	
119	                if (reviewResult instanceof MutationResponse mr) {
120	                    // 审核先提交：看到的是建区前一致状态，只能 CLEAR 且版本为 0
121	                    ReviewResultDto dto = objectMapper.convertValue(mr.data(), ReviewResultDto.class);
122	                    assertEquals("CLEAR", dto.conclusion(),
123	                            "旧空域版本审核不得使用并发新建区域判定");
124	                    assertEquals(0L, dto.airspaceVersion());
