/** 应急走廊状态：只能创建（ACTIVE）或撤销（REVOKED）；是否当前有效另按时间窗判定。 */
public enum CorridorStatus {
    /** 走廊未撤销；在 [startUtc, endUtc) 时间窗内视为有效。 */
    ACTIVE,
    /** 走廊已撤销；撤销只影响后续占用，已让渡占用不自动恢复，记录保留不可变。 */
    REVOKED
}

package com.example.starter.domain;

/** 空域占用类型。 */
public enum OccupancyKind {
    /** 常规占用：命中有效应急走廊时必须让渡；新建时命中有效走廊返回 409。 */
    REGULAR,
    /** 应急占用：允许使用有效走廊覆盖的路径段，但仍必须通过既有禁飞区审查。 */
    EMERGENCY
}

package com.example.starter.domain;

/** 空域占用状态。 */
public enum OccupancyStatus {
    /** 有效占用：登记后尚未让渡。 */
    REGULAR_ACTIVE,
    /**
     * 已让渡给应急走廊：在同一走廊创建事务内由 ACTIVE 转入，
     * 固化原审查版本与让渡原因；不自动恢复，必须重新审查并显式重新申请。
     */
    YIELDED
}

package com.example.starter.domain;

/** 占用处置不可变事件类型。 */
public enum OccupancyEventType {
    /** 占用登记（常规或应急）。 */
    CREATED,
    /** 常规占用在走廊创建事务内被让渡。 */
    YIELDED,
    /** 已让渡原占用经重新审查后显式重新申请。 */
    REAPPLIED,
    /** 起飞登记。 */
    DEPARTED
}

