48	    static final String KIND_ZONE_REVOKE = "ZONE_REVOKE";
49	    static final String KIND_ROUTE_CREATE = "ROUTE_CREATE";
50	    static final String KIND_ROUTE_REPLACE = "ROUTE_REPLACE";
