76	    /** 创建禁飞区；同键同参重放原结果，异参 409。 */
77	    public MutationResponse createZone(ZoneCreateRequest request) {
78	        return idempotency.execute(request.requestId(), KIND_ZONE_CREATE, request, () -> {
79	            if (request.xMin() >= request.xMax() || request.yMin() >= request.yMax()) {
80	                throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ZONE_RECTANGLE",
81	                        "禁飞区必须是非退化轴对齐矩形：xMin < xMax 且 yMin < yMax");
82	            }
83	            if (airspaceRepo.findZone(request.zoneId()) != null) {
84	                throw new ApiException(HttpStatus.CONFLICT, "ZONE_ALREADY_EXISTS",
85	                        "禁飞区已存在: " + request.zoneId());
86	            }
87	            long newVersion = airspaceRepo.incrementGlobalVersion();
88	            airspaceRepo.insertZone(new ZonePo(request.zoneId(), request.xMin(), request.yMin(),
89	                    request.xMax(), request.yMax(), ZoneStatus.ACTIVE.name(), newVersion, null));
