96	    public MutationResponse revokeZone(ZoneRevokeRequest request) {
97	        return idempotency.execute(request.requestId(), KIND_ZONE_REVOKE, request, () -> {
98	            ZonePo zone = airspaceRepo.findZone(request.zoneId());
99	            if (zone == null) {
100	                throw new ApiException(HttpStatus.NOT_FOUND, "ZONE_NOT_FOUND",
