106	            }
107	            long newVersion = airspaceRepo.incrementGlobalVersion();
108	            airspaceRepo.markRevoked(request.zoneId(), newVersion);
109	            return new MutationResponse(request.requestId(), false,
110	                    new ZoneResult(request.zoneId(), ZoneStatus.REVOKED.name(), newVersion));
111	        });
112	    }
