117	    public MutationResponse createRoute(RouteCreateRequest request) {
118	        return idempotency.execute(request.requestId(), KIND_ROUTE_CREATE, request, () -> {
119	            List<Point> points = toPoints(request.points());
120	            validatePointsDistinct(points);
