            rs.getLong("created_at"),
            (Long) rs.getObject("departed_at"));

    private static final RowMapper<YieldRecordPo> YIELD_MAPPER = (rs, n) -> new YieldRecordPo(
            rs.getLong("seq"),
            rs.getString("occupancy_id"),
            rs.getString("corridor_id"),
