    public static final String KIND_DEPARTURE_REGISTER = "DEPARTURE_REGISTER";

    /** 建立应急走廊：相交的可让渡常规 ACTIVE 占用同事务标 YIELDED；存在不可让渡或已起飞占用时 422。 */
