        // 三段：段0 远离；段1 水平穿过矩形（y=10, x 0..100）；段2 远离
        List<Point> three = List.of(
                new Point(0, 0), new Point(100, 0),
                new Point(100, 10), new Point(0, 10),
                new Point(0, -50), new Point(100, -50));
        assertEquals(List.of(1), Geometry.hitSegmentIndexes(three, X_MIN, Y_MIN, X_MAX, Y_MAX));

        // 段0 与段2 命中，顺序升序
        List<Point> skipOne = List.of(
                new Point(0, 10), new Point(100, 10),
                new Point(0, 0), new Point(100, 0),
                new Point(0, 10), new Point(100, 10));
        assertEquals(List.of(0, 2), Geometry.hitSegmentIndexes(skipOne, X_MIN, Y_MIN, X_MAX, Y_MAX));

        // 不相交返回空列表
        List<Point> none = List.of(new Point(-50, -50), new Point(-40, -40));
        assertTrue(Geometry.hitSegmentIndexes(none, X_MIN, Y_MIN, X_MAX, Y_MAX).isEmpty());
    }
}

